<?php
declare(strict_types=1);
namespace CajeerBook;

final class OpenApiView
{
    private static function e(string $s):string{return Markdown::e($s);}
    private static function url(string $s):string{return self::e(WorkspaceUrls::url($s));}
    private static function hidden(string $name,string $value):string{return '<input type="hidden" name="'.self::e($name).'" value="'.self::e($value).'">';}
    private static function field(string $name,string $label,string $value='',string $extra=''):string{return '<label>'.self::e($label).'<input name="'.self::e($name).'" value="'.self::e($value).'" '.$extra.'></label>';}
    public static function render(array $db,string $csrf,array $query=[],?array $preview=null,string $notice=''):string{
        $url=self::url('/studio/openapi');$hidden=self::hidden('csrf',$csrf);$scope=is_string($query['spec']??null)?$query['spec']:'';$selected=$db['openapi'][$scope]??null;
        $book=$selected['book']??'api';$version=$selected['version']??'1.0';$slug=$selected['slug']??'reference';
        $out='<div class="eyebrow">DEVELOPER / OPENAPI</div><h1>OpenAPI Reference</h1><p>Import OpenAPI 3.0 or 3.1 and generate editable draft pages. Publication uses the normal review policy. Do not import credentials or confidential examples into public books.</p><div class="actions"><a href="'.self::url('/studio').'">Studio</a> <a href="'.$url.'">New specification</a></div>';
        if($notice!=='')$out.='<p role="status">'.self::e($notice).'</p>';
        $out.='<h2>Specifications</h2>';
        foreach($db['openapi']??[] as $key=>$s){$last=end($s['revisions']);$out.='<p><a href="'.$url.'?spec='.rawurlencode($key).'">'.self::e($last['title']).'</a> — '.self::e($s['book'].' / '.$s['version'].' / '.$s['slug']).' · '.self::e($last['api_version']).' · revision '.$s['revision'].'</p>';}
        if($selected){$out.='<h2>Source history</h2><p>Retained source revisions can be regenerated into drafts. A restore creates a new source revision, not a publication.</p>';foreach(array_reverse($selected['revisions']) as $r){$rev=(string)$r['revision'];$out.='<div class="result"><strong>Revision '.self::e($rev).' · '.self::e($r['api_version']).'</strong> · '.self::e($r['actor']['username'].' · '.$r['at']).'<p>SHA-256: <code>'.self::e($r['sha256']).'</code>'.($r['commit']!==''?' · Git commit <code>'.self::e($r['commit']).'</code>':'').'</p><div class="actions"><a href="'.$url.'?spec='.rawurlencode($scope).'&amp;download='.rawurlencode($rev).'">Download source bundle</a><form method="post" action="'.$url.'">'.$hidden.self::hidden('action','restore-preview').self::hidden('spec',$scope).self::hidden('source_revision',$rev).'<button>Preview this revision</button></form></div></div>';}
            $out.='<h2>Generated pages</h2>';foreach($selected['pages'] as $key=>$m){$out.='<p><a href="'.self::url('/studio?edit='.rawurlencode($key)).'">'.self::e($key).'</a>'.($m['retired']?' · removed from source':'').'</p>';}}
        $target=self::field('book','Book slug',$book,'required maxlength="64"').self::field('version','Book version',$version,'required maxlength="64"').self::field('slug','Specification slug',$slug,'required maxlength="64"');
        $out.='<h2>Import or update</h2><form method="post" enctype="multipart/form-data" action="'.$url.'">'.$hidden.$target.self::field('root','Root filename (relative to bundle)','openapi.yaml','required maxlength="512"').'<label>JSON or YAML source (paste a single document)<textarea name="source" rows="8" maxlength="1048576" placeholder="{ &quot;openapi&quot;: &quot;3.1.0&quot;, ... }"></textarea></label><label>Or upload specification files / ZIP / downloaded source bundle<input type="file" name="files[]" multiple accept=".json,.yaml,.yml,.zip"></label><label>Or select a folder<input type="file" name="directory[]" webkitdirectory multiple></label><button name="action" value="preview">Preview import</button></form>';
        if(isset($db['github']))$out.='<h2>Import from connected Git repository</h2><p>Reads JSON/YAML files from a directory relative to the configured documentation root at a fixed commit SHA.</p><form method="post" action="'.$url.'">'.$hidden.$target.self::field('folder','Git folder relative to documentation root','', 'maxlength="512"').self::field('root','Root filename in folder','openapi.yaml','required maxlength="512"').'<button name="action" value="git-preview">Preview Git specification</button></form>';
        if($preview){$m=$preview['model'];$out.='<h2>Import preview</h2><p>'.self::e($m['title'].' · '.$m['api_version'].' · '.$m['format']).' · '.$m['operations'].' operations · '.$m['schemas'].' schemas</p>'.($preview['commit']!==''?'<p>Git commit: <code>'.self::e($preview['commit']).'</code></p>':'');
            $out.='<table><thead><tr><th>Page</th><th>Change</th><th>Details</th></tr></thead><tbody>';foreach($preview['rows'] as $key=>$r){$out.='<tr><td>'.self::e($r['title']).'<br><small>'.self::e($key).'</small></td><td>'.self::e($r['action']).'</td><td>'.self::e($r['reason']).'</td></tr>';}$out.='</tbody></table>';
            $diffs=0;$diffBytes=0;foreach($preview['rows'] as $key=>$r){if(!in_array($r['action'],['update','removed','conflict'],true)||!isset($db['pages'][$key])||$diffs++>=20)continue;$before=$db['pages'][$key]['draft']['body'];$after=$preview['pages'][$key]['body'];if(($diffBytes+=strlen($before)+strlen($after))>524288)break;$out.='<details><summary>Compare '.self::e($r['title']).'</summary><pre>';foreach(RevisionHistory::diff($before,$after) as [$type,$text]){$out.=self::e(($type==='add'?'+ ':($type==='remove'?'- ':'  ')).$text)."\n";}$out.='</pre></details>';}
            if(!$preview['conflicts']){[$b,$v,,$s]=explode('/',$preview['scope']);$out.='<form method="post" action="'.$url.'">'.$hidden.self::hidden('action','apply').self::hidden('book',$b).self::hidden('version',$v).self::hidden('slug',$s).self::hidden('token',$preview['token']).self::hidden('commit',$preview['commit']).self::hidden('bundle',base64_encode($preview['bundle'])).'<p>All generated changes are committed as drafts. Removed operations retain their prior publication until an authorized action.</p><button class="primary">Apply reference drafts</button></form>';}else $out.='<p>Resolve all conflicts before applying. No documents have changed.</p>';
        }
        return $out;
    }
}
